SELECT 
FROM ai_brief_schedule
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}

mapper.update:
UPDATE ai_brief_schedule
SET


        last_weekly_claim_on = #{claimOn}


        last_daily_claim_on = #{claimOn}


WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND pending_turn_id IS NULL


        AND weekly_enabled = TRUE
        AND (last_weekly_claim_on IS NULL OR last_weekly_claim_on < #{claimOn})


        AND daily_enabled = TRUE
        AND (last_daily_claim_on IS NULL OR last_daily_claim_on < #{claimOn})

UPDATE ai_brief_schedule
SET pending_kind = #{kind},
    pending_session_id = #{sessionId},
    pending_turn_id = #{turnId},
    pending_started_at = #{startedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND pending_turn_id IS NULL

UPDATE ai_brief_schedule
SET last_failure_at = #{at},
    last_failure_reason = #{failureReason}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}

mapper.delete:
DELETE FROM ai_brief_schedule
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
